import sqlite3, os, glob
db='magaza.db'
print('exists', os.path.exists(db), os.getcwd())
print(glob.glob('*.db'))
con=sqlite3.connect(db)
cur=con.cursor()
for row in cur.execute("select name, sql from sqlite_master where type='table'"):
    print(row[0], row[1])
for t in ['musteriler','urunler','siparisler','siparis_kalemleri','iadeler']:
    try:
        print(t, cur.execute(f'select count(*) from {t}').fetchone())
    except Exception as e: print(t,e)
for row in cur.execute('select * from siparisler limit 5'): print(row)
con.close()
